from __future__ import annotations

"""Forward schema extension for the complete BioIntel Connect target."""

MIGRATION_ID = "002_connect_complete_target"


def _model(table: str, key: str, fields: str, constraints: str = "") -> str:
    suffix = f",\n  {constraints}" if constraints.strip() else ""
    return f"""
CREATE TABLE IF NOT EXISTS {table}(
  {key} TEXT PRIMARY KEY,
  creator_id TEXT REFERENCES connect_users(user_id) ON DELETE SET NULL,
  {fields},
  state TEXT NOT NULL DEFAULT 'active', visibility TEXT NOT NULL DEFAULT 'private',
  created_at_utc TEXT NOT NULL, updated_at_utc TEXT NOT NULL, deleted_at_utc TEXT,
  audit_json TEXT NOT NULL DEFAULT '{{}}', version INTEGER NOT NULL DEFAULT 1{suffix}
);"""


